$ErrorActionPreference='Stop'
$js=@'
const port=17447,targetId="AA1D82B7F14CE6896A268FCB2514A214";
const targets=await (await fetch("http://127.0.0.1:"+port+"/json/list")).json();
const target=targets.find(x=>x.id===targetId&&x.type==="page");
if(!target)throw Error("TARGET_MISSING");
const ws=new WebSocket(target.webSocketDebuggerUrl);
await new Promise((ok,no)=>{ws.addEventListener("open",ok,{once:true});ws.addEventListener("error",no,{once:true})});
const p=new Promise((ok,no)=>{ws.addEventListener("message",e=>{try{const x=JSON.parse(e.data);if(x.id===208)ok(x)}catch{}});setTimeout(()=>no(Error("CDP_TIMEOUT")),6000)});
const expression="(()=>{window.scrollBy(0,580);return{scrollY:Math.round(window.scrollY),title:document.title,anchorCount:document.querySelectorAll('a[href]').length}})()";
ws.send(JSON.stringify({id:208,method:"Runtime.evaluate",params:{expression,returnByValue:true,awaitPromise:false}}));
const response=await p;ws.close();
console.log(JSON.stringify({ok:!!response.result?.result?.value,publicPageOnly:true,result:response.result?.result?.value||null,errorCode:response.error?.code||null}));
'@
$tmp=Join-Path $env:TEMP 'pc-avito-managed-scroll-test.mjs'
try{[System.IO.File]::WriteAllText($tmp,$js,[System.Text.UTF8Encoding]::new($false));& node.exe $tmp}finally{Remove-Item -LiteralPath $tmp -ErrorAction SilentlyContinue -Force}
